mapper.select:
SELECT o.outReqId AS outReqId, o.comId AS comId, c.comName AS comName, o.outDateWish AS outDateWish, o.outDttmAppr AS outDttmAppr, /* 코드와 한글 상태 모두 반환 */ CASE WHEN SUM(CASE WHEN i.status = '출고완료' THEN 1 ELSE 0 END) > 0 THEN 'SHIPPED' WHEN SUM(CASE WHEN i.status = '승인완료' THEN 1 ELSE 0 END) > 0 THEN 'APPROVED' WHEN SUM(CASE WHEN i.status = '반려' THEN 1 ELSE 0 END) > 0 THEN 'CANCELLED' WHEN SUM(CASE WHEN i.status = '검수중' THEN 1 ELSE 0 END) > 0 THEN 'INSPECTING' ELSE 'REQUESTED' END AS status, CASE WHEN SUM(CASE WHEN i.status = '출고완료' THEN 1 ELSE 0 END) > 0 THEN '출고완료' WHEN SUM(CASE WHEN i.status = '승인완료' THEN 1 ELSE 0 END) > 0 THEN '승인완료' WHEN SUM(CASE WHEN i.status = '반려' THEN 1 ELSE 0 END) > 0 THEN '반려' WHEN SUM(CASE WHEN i.status = '검수중' THEN 1 ELSE 0 END) > 0 THEN '검수중' ELSE '승인대기' END AS statusValue, o.IsTempo AS isTempo, o.IsDelete AS isDelete, o.outDttmReq AS createdAt FROM outboundrequest o LEFT JOIN companies c ON c.comId = o.comId LEFT JOIN outbounditems i ON i.outReqId = o.outReqId WHERE o.IsDelete = 0
AND c.comName LIKE CONCAT('%', #{comName}, '%')
AND ( (#{status} = 'SHIPPED' AND EXISTS (SELECT 1 FROM outbounditems x WHERE x.outReqId=o.outReqId AND x.status='출고완료')) OR (#{status} = 'APPROVED' AND EXISTS (SELECT 1 FROM outbounditems x WHERE x.outReqId=o.outReqId AND x.status='승인완료')) OR (#{status} = 'CANCELLED' AND EXISTS (SELECT 1 FROM outbounditems x WHERE x.outReqId=o.outReqId AND x.status='반려')) OR (#{status} = 'INSPECTING' AND EXISTS (SELECT 1 FROM outbounditems x WHERE x.outReqId=o.outReqId AND x.status='검수중')) OR (#{status} = 'REQUESTED' AND NOT EXISTS (SELECT 1 FROM outbounditems x WHERE x.outReqId=o.outReqId AND x.status IN ('출고완료','승인완료','반려','검수중'))) )
AND DATE(o.outDttmReq) >= #{startDate}
AND DATE(o.outDttmReq) <= #{endDate}
GROUP BY o.outReqId, o.comId, c.comName, o.outDateWish, o.outDttmReq, o.outDttmAppr, o.IsTempo, o.IsDelete ORDER BY o.outDttmReq DESC

{ CALL CreateOutReq(
